def category(name):
    if name.endswith(".txt"):
        return "text"
    elif name.endswith(".csv"):
        return "data"
    return "other"

raw = " A.TXT, b.csv, a.txt, photo.png "
seen = {}
for part in raw.split(","):
    name = part.strip().lower()
    if name == "":
        continue
    if name in seen:
        print(f"duplicate:{name}")
    else:
        seen[name] = True
        print(f"{category(name)}:{name}")
print(f"total={len(seen)}")

